//! Golden tests for `pos::*` and `BoundingBox` against vanilla output.
//! Fixture: `tests/fixtures/pos/pos_golden.txt`, generated by `PosOracle.java` (same directory).
//! Every line is `<tag> <inputs> => <outputs>`; the Rust side recomputes the outputs from the inputs and
//! compares token by token (tokens prefixed `F:` in our output are doubles compared by value).
use mc_core::bounding_box::BoundingBox;
use mc_core::direction::{Axis, AxisCycle, Direction};
use mc_core::pos::block_pos::{self, TraversalNodeStatus};
use mc_core::pos::{quart_pos, BlockPos, ChunkPos, Cursor3D, MutableBlockPos, SectionPos, Vec3i};
use mc_core::phys::{Vec3, AABB};
use mc_core::random::{LegacyRandomSource, RandomSource};
use mc_core::rotation::Rotation;

const GOLDEN: &str = include_str!("../fixtures/pos/pos_golden.txt");

fn int(s: &str) -> i32 {
    s.parse().unwrap_or_else(|_| panic!("bad int {s:?}"))
}

fn long(s: &str) -> i64 {
    s.parse().unwrap()
}

fn dbl(s: &str) -> f64 {
    f64::from_bits(s.parse::<i64>().unwrap() as u64)
}

fn ints(s: &str) -> Vec<i32> {
    s.split(',').map(int).collect()
}

fn bp(s: &str) -> BlockPos {
    let v = ints(s);
    BlockPos::new(v[0], v[1], v[2])
}

fn v3i(s: &str) -> Vec3i {
    let v = ints(s);
    Vec3i::new(v[0], v[1], v[2])
}

fn bbox(s: &str) -> BoundingBox {
    let v = ints(s);
    BoundingBox::new(v[0], v[1], v[2], v[3], v[4], v[5])
}

fn p(v: &Vec3i) -> String {
    format!("{},{},{}", v.x, v.y, v.z)
}

fn cp(c: &ChunkPos) -> String {
    format!("{},{}", c.x, c.z)
}

fn bb(b: &BoundingBox) -> String {
    format!("{},{},{},{},{},{}", b.min_x(), b.min_y(), b.min_z(), b.max_x(), b.max_y(), b.max_z())
}

fn list(it: impl Iterator<Item = BlockPos>) -> String {
    let s: Vec<String> = it.map(|b| p(&b)).collect();
    if s.is_empty() { "-".into() } else { s.join(";") }
}

fn dir(name: &str) -> Direction {
    Direction::by_name(name).unwrap_or_else(|| panic!("bad direction {name}"))
}

fn f(x: f64) -> String {
    format!("F:{x:?}")
}

fn check(line_no: usize, tag: &str, expected: &str, actual: &[String]) {
    let actual = actual.join(" ");
    let (e, a): (Vec<&str>, Vec<&str>) = (expected.split(' ').collect(), actual.split(' ').collect());
    let mut ok = e.len() == a.len();
    if ok {
        for (e, a) in e.iter().zip(&a) {
            ok &= match a.strip_prefix("F:") {
                Some(a) => {
                    let (e, a): (f64, f64) = (e.parse().unwrap(), a.parse().unwrap());
                    e.to_bits() == a.to_bits() || (e.is_nan() && a.is_nan())
                }
                None => e == a,
            };
        }
    }
    assert!(ok, "line {line_no} [{tag}]:\n  expected: {expected}\n  actual:   {actual}");
}

fn rotations() -> [Rotation; 4] {
    Rotation::ALL
}

#[test]
fn golden() {
    let mut seen = std::collections::BTreeMap::<&str, usize>::new();
    for (i, line) in GOLDEN.lines().enumerate() {
        let line_no = i + 1;
        let (lhs, expected) = line.split_once(" => ").unwrap_or_else(|| (line.strip_suffix(" =>").unwrap(), ""));
        let mut t = lhs.split(' ');
        let tag = t.next().unwrap();
        let a: Vec<&str> = t.collect();
        *seen.entry(tag).or_default() += 1;
        let out: Vec<String> = match tag {
            "const" => {
                assert_eq!(
                    [a[0], a[1], a[2], a[3], a[4]].map(|s| s.to_string()),
                    [
                        block_pos::PACKED_HORIZONTAL_LENGTH.to_string(),
                        block_pos::PACKED_Y_LENGTH.to_string(),
                        block_pos::MAX_HORIZONTAL_COORDINATE.to_string(),
                        ChunkPos::MAX_CHUNK_COORDINATE_VALUE.to_string(),
                        ChunkPos::INVALID_CHUNK_POS.to_string()
                    ]
                );
                vec!["ok".into()]
            }
            "bp_aslong" => vec![BlockPos::as_long_xyz(int(a[0]), int(a[1]), int(a[2])).to_string()],
            "bp_unpack" => {
                let l = long(a[0]);
                let b = BlockPos::of_long(l);
                vec![
                    BlockPos::get_x(l).to_string(),
                    BlockPos::get_y(l).to_string(),
                    BlockPos::get_z(l).to_string(),
                    p(&b),
                    BlockPos::get_flat_index(l).to_string(),
                    SectionPos::block_to_section(l).to_string(),
                    ChunkPos::pack_block_pos(&b).to_string(),
                ]
            }
            "bp_offset" => vec![BlockPos::offset_long(long(a[0]), int(a[1]), int(a[2]), int(a[3])).to_string()],
            "bp_offset_dir" => vec![BlockPos::offset_long_direction(long(a[0]), dir(a[1])).to_string()],
            "vec3i" => {
                let (va, vb) = (v3i(a[0]), v3i(a[1]));
                let exp_cmp = int(expected.split(' ').nth(1).unwrap());
                let diff = |x: i32, y: i32| x as i64 - y as i64;
                if [diff(va.y, vb.y), diff(va.z, vb.z), diff(va.x, vb.x)].iter().all(|d| i32::try_from(*d).is_ok()) {
                    assert_eq!(va.cmp(&vb) as i32, exp_cmp.signum(), "line {line_no} Ord");
                }
                vec![
                    va.hash_code().to_string(),
                    va.compare_to(&vb).to_string(),
                    va.dist_manhattan(&vb).to_string(),
                    va.dist_chessboard(&vb).to_string(),
                    p(&va.cross(&vb)),
                    f(va.dist_sqr(&vb)),
                    va.closer_than(&vb, 100.5).to_string(),
                    va.differs_horizontally(&vb).to_string(),
                    p(&va.offset_vec(&vb)),
                    p(&va.subtract(&vb)),
                    p(&va.multiply(3)),
                    p(&va.multiply(0)),
                    p(&va.multiply_xyz(va.y, 5, -7)),
                    va.to_string(),
                    va.to_short_string(),
                ]
            }
            "bp_ops" => {
                let (pa, vb) = (bp(a[0]), v3i(a[1]));
                let mut o = vec![];
                for d in Direction::ALL {
                    o.push(p(&pa.relative(d)));
                    o.push(p(&pa.relative_n(d, 3)));
                }
                for ax in Axis::ALL {
                    o.push(p(&pa.relative_axis(ax, -4)));
                }
                for r in rotations() {
                    o.push(p(&pa.rotate(r)));
                }
                let pb = BlockPos::new(vb.x, vb.y, vb.z);
                o.extend([
                    p(&pa.above()),
                    p(&pa.below_n(2)),
                    p(&pa.north()),
                    p(&pa.south_n(5)),
                    p(&pa.west()),
                    p(&pa.east_n(2)),
                    p(&pa.at_y(77)),
                    p(&pa.offset_vec(&vb)),
                    p(&pa.subtract(&vb)),
                    p(&pa.multiply(-2)),
                    p(&pa.cross(&vb)),
                    pa.get(Axis::Y).to_string(),
                    p(&BlockPos::min(&pa, &pb)),
                    p(&BlockPos::max(&pa, &pb)),
                    pa.to_string(),
                    pa.mutable().to_string(),
                    pa.hash_code().to_string(),
                ]);
                o
            }
            "bp_containing" => {
                let (x, y, z) = (dbl(a[0]), dbl(a[1]), dbl(a[2]));
                let q = bp(a[3]);
                let cl = q.clamp_location_within(&Vec3::new(x, y, z));
                let bits = |d: f64| (d.to_bits() as i64).to_string();
                vec![
                    p(&BlockPos::containing(x, y, z)),
                    bits(cl.x),
                    bits(cl.y),
                    bits(cl.z),
                    bits(q.dist_to_center_sqr_xyz(x, y, z)),
                    bits(q.dist_to_low_corner_sqr(x, y, z)),
                    q.closer_to_center_than(&Vec3::new(x, y, z), 2.5).to_string(),
                    p(&SectionPos::of_position(&Vec3::new(x, y, z)).origin()),
                    SectionPos::pos_to_section_coord(x).to_string(),
                ]
            }
            "mutable" => {
                let s = bp(a[0]);
                let (ax, ay, az) = (s.x, s.y, s.z);
                let mut m = MutableBlockPos::new(ax, ay, az);
                let mut o = vec![];
                m.move_dir(Direction::North);
                o.push(m.to_string());
                m.move_dir_n(Direction::Up, 3);
                o.push(m.to_string());
                m.move_by(-2, 5, 7);
                o.push(m.to_string());
                m.move_vec(&Vec3i::new(1, 2, 3));
                o.push(m.to_string());
                let q = Vec3i::new(az, ax, ay);
                m.set_with_offset_direction(&q, Direction::West);
                o.push(m.to_string());
                m.set_with_offset(&q, 4, 5, 6);
                o.push(m.to_string());
                m.set_with_offset_vec(&q, &Vec3i::new(-1, -2, -3));
                o.push(m.to_string());
                m.clamp(Axis::X, -5, 5);
                o.push(m.to_string());
                m.clamp(Axis::Y, 0, 10);
                o.push(m.to_string());
                m.clamp(Axis::Z, -3, 3);
                o.push(m.to_string());
                m.set_f64(1.7, -2.3, 9.99);
                o.push(m.to_string());
                m.set_long(BlockPos::as_long_xyz(ax, ay, az));
                o.push(m.to_string());
                m.set_axis_cycle(AxisCycle::Forward, 1, 2, 3);
                o.push(m.to_string());
                m.set_axis_cycle(AxisCycle::Backward, 1, 2, 3);
                o.push(m.to_string());
                m.set_x(9).set_y(8).set_z(7);
                o.push(m.to_string());
                o.extend([
                    m.immutable().to_string(),
                    m.offset(1, 1, 1).to_string(),
                    m.relative_n(Direction::East, 2).to_string(),
                    m.rotate(Rotation::Clockwise90).to_string(),
                    m.multiply(4).to_string(),
                    (*m == BlockPos::new(9, 8, 7)).to_string(),
                    m.hash_code().to_string(),
                ]);
                o
            }
            "mutable_dbl" => vec![MutableBlockPos::from_f64(1.9, -0.1, 3.5).to_string()],
            "spiral" => vec![list(BlockPos::spiral_around(&bp(a[0]), int(a[1]), dir(a[2]), dir(a[3])))],
            "manhattan" => vec![list(BlockPos::within_manhattan(&bp(a[0]), int(a[1])))],
            "clipped_manhattan" => vec![list(BlockPos::within_clipped_manhattan(&bp(a[0]), int(a[1]), int(a[2]), int(a[3])))],
            "box_manhattan" => vec![list(BlockPos::within_box_by_manhattan_distance(&bp(a[0]), int(a[1]), int(a[2]), int(a[3])))],
            "between_closed" => vec![list(BlockPos::between_closed(&bp(a[0]), &bp(a[1])))],
            "between_closed_xyz" => {
                let v: Vec<i32> = a.iter().map(|s| int(s)).collect();
                vec![list(BlockPos::between_closed_xyz(v[0], v[1], v[2], v[3], v[4], v[5]))]
            }
            "between_closed_box" => vec![list(BlockPos::between_closed_box(&bbox(a[0])))],
            "between_closed_aabb" => {
                let d: Vec<f64> = a.iter().map(|s| dbl(s)).collect();
                let l = list(BlockPos::between_closed_aabb(&AABB::new(d[0], d[1], d[2], d[3], d[4], d[5])));
                vec![l.clone(), "|".into(), l]
            }
            "neighbor_column" => vec![list(BlockPos::neighbor_column(int(a[0]), int(a[1]), int(a[2]), int(a[3])))],
            "corners_dir" => {
                let v: Vec<i32> = a[..6].iter().map(|s| int(s)).collect();
                let dv = Vec3::new(dbl(a[6]), dbl(a[7]), dbl(a[8]));
                vec![list(BlockPos::between_corners_in_direction_xyz(v[0], v[1], v[2], v[3], v[4], v[5], dv))]
            }
            "corners_dir_aabb" => {
                let dv = Vec3::new(dbl(a[0]), dbl(a[1]), dbl(a[2]));
                vec![list(BlockPos::between_corners_in_direction_aabb(&AABB::new(-0.5, 0.2, 1.7, 1.3, 2.4, 2.1), dv))]
            }
            "random_between" => {
                let mut rs = LegacyRandomSource::new(long(a[0]));
                let l = list(BlockPos::random_between_closed(&mut rs, 7, -3, 4, 5, 5, 10, 9));
                vec![l, format!("next={}", rs.next_int())]
            }
            "random_cube" => {
                let mut rs = LegacyRandomSource::new(long(a[0]));
                let l = list(BlockPos::random_in_cube(&mut rs, 6, &BlockPos::new(1, 2, 3), 4));
                vec![l, format!("next={}", rs.next_int())]
            }
            "bfs" => {
                let variant = int(a[0]);
                let mut visited: Vec<String> = vec![];
                let res = BlockPos::breadth_first_traversal(
                    BlockPos::ZERO,
                    int(a[1]),
                    int(a[2]),
                    |pos, consumer| {
                        for d in Direction::HORIZONTAL {
                            consumer(pos.relative(d));
                        }
                        consumer(pos.above());
                        consumer(pos.relative(Direction::North));
                    },
                    |pos| {
                        visited.push(p(&pos));
                        let h = (pos.x.wrapping_mul(31).wrapping_add(pos.y.wrapping_mul(17)).wrapping_add(pos.z.wrapping_mul(13))).rem_euclid(11);
                        if h == 3 {
                            TraversalNodeStatus::Skip
                        } else if variant == 3 && h == 9 {
                            TraversalNodeStatus::Stop
                        } else {
                            TraversalNodeStatus::Accept
                        }
                    },
                );
                vec![res.to_string(), visited.join(";")]
            }
            "section" => {
                let (x, y, z) = (int(a[0]), int(a[1]), int(a[2]));
                let rnd = a[3].parse::<i16>().unwrap();
                let s = SectionPos::of(x, y, z);
                let b = BlockPos::new(x, y, z);
                let rel = SectionPos::section_relative_pos(&b);
                let l = s.as_long();
                vec![
                    l.to_string(),
                    SectionPos::x_from_long(l).to_string(),
                    SectionPos::y_from_long(l).to_string(),
                    SectionPos::z_from_long(l).to_string(),
                    p(&SectionPos::of_long(l)),
                    SectionPos::as_long_block_pos(&b).to_string(),
                    p(&SectionPos::of_block_pos(&b)),
                    s.min_block_x().to_string(),
                    s.min_block_y().to_string(),
                    s.min_block_z().to_string(),
                    s.max_block_x().to_string(),
                    s.max_block_y().to_string(),
                    s.max_block_z().to_string(),
                    p(&s.origin()),
                    p(&s.center()),
                    cp(&s.chunk()),
                    SectionPos::get_zero_node(l).to_string(),
                    SectionPos::get_zero_node_xz(x, z).to_string(),
                    SectionPos::section_to_chunk(l).to_string(),
                    rel.to_string(),
                    SectionPos::section_relative_x(rel).to_string(),
                    SectionPos::section_relative_y(rel).to_string(),
                    SectionPos::section_relative_z(rel).to_string(),
                    SectionPos::section_relative_x(rnd).to_string(),
                    SectionPos::section_relative_y(rnd).to_string(),
                    SectionPos::section_relative_z(rnd).to_string(),
                    s.relative_to_block_x(rnd).to_string(),
                    s.relative_to_block_y(rnd).to_string(),
                    s.relative_to_block_z(rnd).to_string(),
                    p(&s.relative_to_block_pos(rnd)),
                    SectionPos::block_to_section_coord_i32(x).to_string(),
                    SectionPos::section_relative(y).to_string(),
                    SectionPos::section_to_block_coord(z).to_string(),
                    SectionPos::section_to_block_coord_offset(x, 9).to_string(),
                    p(&s.offset(1, -2, 3)),
                    SectionPos::offset_long(l, 1, -2, 3).to_string(),
                    SectionPos::offset_long_direction(l, Direction::West).to_string(),
                    s.to_string(),
                    s.hash_code().to_string(),
                ]
            }
            "section_dbl" => {
                let d = dbl(a[0]);
                vec![SectionPos::block_to_section_coord_f64(d).to_string(), SectionPos::pos_to_section_coord(d).to_string()]
            }
            "section_around" => {
                let (x, y, z) = (int(a[0]), int(a[1]), int(a[2]));
                let (mut g1, mut g2) = (vec![], vec![]);
                SectionPos::around_and_at_block_pos(&BlockPos::new(x, y, z), |l| g1.push(l));
                SectionPos::around_and_at_block_pos_long(BlockPos::as_long_xyz(x, y, z), |l| g2.push(l));
                let fmt = |v: &[i64]| format!("[{}]", v.iter().map(|l| l.to_string()).collect::<Vec<_>>().join(", "));
                vec![fmt(&g1), fmt(&g2)]
            }
            "section_cube" => vec![list(SectionPos::cube(&SectionPos::of(2, -1, 3), 1).map(|s| BlockPos::new(s.x, s.y, s.z)))],
            "section_around_chunk" => vec![list(SectionPos::around_chunk(&ChunkPos::new(1, -2), 1, -2, 0).map(|s| BlockPos::new(s.x, s.y, s.z)))],
            "section_blocks_inside" => vec![list(SectionPos::of(-1, 0, 1).blocks_inside())],
            "chunk" => {
                let (x, z, y) = (int(a[0]), int(a[1]), int(a[2]));
                let c = ChunkPos::new(x, z);
                let k = c.pack();
                let b = BlockPos::new(y, x, z);
                vec![
                    k.to_string(),
                    cp(&ChunkPos::unpack(k)),
                    ChunkPos::get_x(k).to_string(),
                    ChunkPos::get_z(k).to_string(),
                    c.hash_code().to_string(),
                    c.is_valid().to_string(),
                    c.get_middle_block_x().to_string(),
                    c.get_middle_block_z().to_string(),
                    c.get_min_block_x().to_string(),
                    c.get_min_block_z().to_string(),
                    c.get_max_block_x().to_string(),
                    c.get_max_block_z().to_string(),
                    c.get_region_x().to_string(),
                    c.get_region_z().to_string(),
                    ChunkPos::get_region_x_from_long(k).to_string(),
                    ChunkPos::get_region_z_from_long(k).to_string(),
                    c.get_region_local_x().to_string(),
                    c.get_region_local_z().to_string(),
                    p(&c.get_block_at(3, y, 4)),
                    c.get_block_x(5).to_string(),
                    c.get_block_z(6).to_string(),
                    p(&c.get_middle_block_position(y)),
                    c.contains(&b).to_string(),
                    c.to_string(),
                    p(&c.get_world_position()),
                    cp(&ChunkPos::containing(&b)),
                    ChunkPos::pack_block_pos(&b).to_string(),
                    ChunkPos::from_section_node(SectionPos::as_long_xyz(x, y, z)).to_string(),
                    cp(&ChunkPos::min_from_region(x, z)),
                    cp(&ChunkPos::max_from_region(x, z)),
                    ChunkPos::is_valid_xz(x, z).to_string(),
                    ChunkPos::hash_xz(z, x).to_string(),
                ]
            }
            "chunk_dist" => {
                let (c, o) = (cpos(a[0]), cpos(a[1]));
                vec![c.get_chessboard_distance(&o).to_string(), c.distance_squared(&o).to_string(), c.distance_squared_long(o.pack()).to_string()]
            }
            "chunk_contains" => vec![cpos(a[1]).contains(&bp(a[0])).to_string()],
            "chunk_range" => vec![ChunkPos::range_closed_between(&cpos(a[0]), &cpos(a[1])).map(|c| cp(&c) + ";").collect::<String>()],
            "chunk_range_radius" => vec![ChunkPos::range_closed(&ChunkPos::new(7, -7), int(a[0])).map(|c| cp(&c) + ";").collect::<String>()],
            "quart" => {
                let x = int(a[0]);
                vec![
                    quart_pos::from_block(x).to_string(),
                    quart_pos::quart_local(x).to_string(),
                    quart_pos::to_block(x).to_string(),
                    quart_pos::from_section(x).to_string(),
                    quart_pos::to_section(x).to_string(),
                ]
            }
            "cursor3d" => {
                let v: Vec<i32> = a.iter().map(|s| int(s)).collect();
                let mut cur = Cursor3D::new(v[0], v[1], v[2], v[3], v[4], v[5]);
                let mut s = String::new();
                let mut n = 0;
                while cur.advance() && {
                    n += 1;
                    n <= 200
                } {
                    s += &format!("{},{},{},{};", cur.next_x(), cur.next_y(), cur.next_z(), cur.get_next_type());
                }
                vec![if s.is_empty() { "-".into() } else { s }]
            }
            "bbox" => {
                let (ba, bb_, pt) = (bbox(a[0]), bbox(a[1]), bp(a[2]));
                let mut mv = ba;
                mv.move_(3, -4, 5);
                let mut mv2 = ba;
                mv2.move_vec(&Vec3i::new(-1, 2, -3));
                let mut en = ba;
                en.encapsulate(&bb_);
                let mut ep = ba;
                ep.encapsulate_pos(&pt);
                let mut corners = String::new();
                ba.for_all_corners(|c| corners += &format!("{};", p(&c)));
                let chunks = if (ba.max_x() as i64 - ba.min_x() as i64) < 200 && (ba.max_z() as i64 - ba.min_z() as i64) < 200 {
                    ba.intersecting_chunks().map(|c| cp(&c) + ";").collect::<String>()
                } else {
                    "-".into()
                };
                vec![
                    ba.intersects(&bb_).to_string(),
                    ba.intersects_xyz(bb_.min_x(), bb_.min_y(), bb_.min_z(), bb_.max_x(), bb_.max_y(), bb_.max_z()).to_string(),
                    ba.intersects_xz(bb_.min_x(), bb_.min_z(), bb_.max_x(), bb_.max_z()).to_string(),
                    bb(&BoundingBox::encapsulating(&ba, &bb_)),
                    bb(&en),
                    bb(&ep),
                    bb(&mv),
                    bb(&mv2),
                    bb(&ba.moved(7, 8, -9)),
                    bb(&ba.inflated_by(2)),
                    bb(&ba.inflated_by_xyz(1, -3, 4)),
                    ba.is_inside(&pt).to_string(),
                    ba.is_inside_xyz(pt.x, pt.y, pt.z).to_string(),
                    p(&ba.get_length()),
                    ba.get_x_span().to_string(),
                    ba.get_y_span().to_string(),
                    ba.get_z_span().to_string(),
                    p(&ba.get_center()),
                    corners,
                    ba.to_string(),
                    (ba == bb_).to_string(),
                    ba.hash_code().to_string(),
                    bb(&BoundingBox::from_corners(&Vec3i::new(ba.min_x(), ba.min_y(), ba.min_z()), &Vec3i::new(bb_.min_x(), bb_.min_y(), bb_.min_z()))),
                    bb(&BoundingBox::from_block_pos(&pt)),
                    chunks,
                ]
            }
            "bbox_infinite" => vec![bb(&BoundingBox::infinite())],
            "bbox_orient" => {
                let d = dir(a[0]);
                vec![
                    bb(&BoundingBox::orient_box(10, 20, 30, 1, 2, 3, 4, 5, 6, d)),
                    bb(&BoundingBox::orient_box(-3, 0, 7, 0, 0, 0, 1, 1, 1, d)),
                    bb(&BoundingBox::orient_box(0, 64, 0, -2, 1, -4, 7, 3, 9, d)),
                ]
            }
            "bbox_encap_pos" => {
                let r = BoundingBox::encapsulating_positions(a[0].split(';').map(bp)).unwrap();
                vec![bb(&r), format!("empty={}", BoundingBox::encapsulating_positions(std::iter::empty()).is_some())]
            }
            "bbox_encap_boxes" => {
                let r = BoundingBox::encapsulating_boxes(a[0].split(';').map(bbox)).unwrap();
                vec![bb(&r), format!("empty={}", BoundingBox::encapsulating_boxes(std::iter::empty()).is_some())]
            }
            other => panic!("line {line_no}: unknown tag {other}"),
        };
        check(line_no, tag, expected, &out);
    }
    // every tag family must actually have been exercised
    assert!(seen.len() == 42, "fixture shrank: {seen:?}");
}

fn cpos(s: &str) -> ChunkPos {
    let v = ints(s);
    ChunkPos::new(v[0], v[1])
}
